/**
 * Regenerate android/ and rebuild, without losing the hand-made Gradle settings.
 *
 * Why this exists: android/ is a prebuild artifact and is gitignored, but four
 * lines in android/gradle.properties are NOT generated by Expo -- they were set
 * by hand to take the APK from 112MB to 37MB:
 *
 *     reactNativeArchitectures=arm64-v8a
 *     android.enableMinifyInReleaseBuilds=true
 *     android.enableShrinkResourcesInReleaseBuilds=true
 *
 * `expo prebuild` regenerates that file and silently drops all of them, so the
 * next APK would be three times the size with no error to explain it. Adding a
 * config plugin (googleServicesFile, expo-notifications) REQUIRES a prebuild,
 * so this script does the prebuild and puts the settings back.
 *
 *   node scripts/rebuild-native.mjs           # prebuild + restore + verify
 *   node scripts/rebuild-native.mjs --build   # ...then assembleRelease
 */
import { execSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';

const PROPS = 'android/gradle.properties';

// [key, value] -- restored after prebuild, in order.
const REQUIRED = [
  ['reactNativeArchitectures', 'arm64-v8a'],
  ['android.enableMinifyInReleaseBuilds', 'true'],
  ['android.enableShrinkResourcesInReleaseBuilds', 'true'],
  // Expo's default is MaxMetaspaceSize=512m, which the build outgrew once
  // expo-updates was added -- Gradle failed with the single word "Metaspace".
  // Same class of loss as the settings above: regenerated, and silent.
  ['org.gradle.jvmargs', '-Xmx3072m -XX:MaxMetaspaceSize=1024m'],
];

const run = (cmd, cwd) => {
  console.log('\n$ ' + cmd + (cwd ? '   (in ' + cwd + ')' : ''));
  // cwd rather than "cd android && ...": cmd.exe does not resolve a .bat file
  // from the current directory without a leading .\, so the chained form died
  // with "gradlew.bat is not recognized" AFTER a successful prebuild.
  execSync(cmd, { stdio: 'inherit', cwd });
};

// A config plugin that points at a missing file fails the prebuild with a
// confusing error, so check the obvious one first.
const appJson = JSON.parse(readFileSync('app.json', 'utf8'));
const gsf = appJson.expo?.android?.googleServicesFile;
if (gsf && !existsSync(gsf.replace(/^\.\//, ''))) {
  console.error(
    '\nERROR: app.json points android.googleServicesFile at ' + gsf + ', which does not exist.\n' +
      'Download it from the Firebase console first -- see PUSH-SETUP.md.\n'
  );
  process.exit(1);
}

if (!appJson.expo?.extra?.eas?.projectId) {
  console.warn(
    '\nWARNING: no extra.eas.projectId in app.json, so this build cannot obtain a\n' +
      'push token. Everything else works. Run `eas init` to add one.\n'
  );
}

// prebuild DELETES android/local.properties, which holds sdk.dir. Without it
// Gradle fails with "SDK location not found" -- and ANDROID_HOME is not set on
// this machine, so there is no fallback. Captured before, restored after.
const LOCAL_PROPS = 'android/local.properties';
const savedLocalProps = existsSync(LOCAL_PROPS) ? readFileSync(LOCAL_PROPS, 'utf8') : null;

// Stamp first, so prebuild picks up the new versionCode and the bundle picks
// up the new extra.buildNumber. Forgetting this is how every APK ended up
// reporting the same version.
run('node scripts/stamp-build.mjs');

run('npx expo prebuild --platform android');

if (savedLocalProps !== null && !existsSync(LOCAL_PROPS)) {
  writeFileSync(LOCAL_PROPS, savedLocalProps);
  console.log('');
  console.log('Restored ' + LOCAL_PROPS + ' (prebuild removes it)');
} else if (!existsSync(LOCAL_PROPS) && !process.env.ANDROID_HOME) {
  console.error('');
  console.error('ERROR: no android/local.properties and no ANDROID_HOME.');
  console.error('Gradle cannot find the Android SDK. Create the file with, for example:');
  console.error('  sdk.dir=C:/Users/<you>/AppData/Local/Android/Sdk');
  console.error('');
  process.exit(1);
}

// ---- put the hand-made settings back ----
let props = readFileSync(PROPS, 'utf8');
const restored = [];

for (const [key, value] of REQUIRED) {
  const line = key + '=' + value;
  const re = new RegExp('^' + key.replace(/[.]/g, '[.]') + '=.*$', 'm');

  if (re.test(props)) {
    props = props.replace(re, line);
  } else {
    props = props.trimEnd() + '\n' + line + '\n';
    restored.push(key);
  }
}

writeFileSync(PROPS, props);

// ---- verify, rather than trust ----
const after = readFileSync(PROPS, 'utf8');
let ok = true;
for (const [key, value] of REQUIRED) {
  const present = new RegExp('^' + key.replace(/[.]/g, '[.]') + '=' + value + '$', 'm').test(after);
  console.log((present ? '  ok   ' : '  MISS ') + key + '=' + value);
  if (!present) ok = false;
}
if (!ok) {
  console.error('\nERROR: a required Gradle setting is missing. Do not ship this build.\n');
  process.exit(1);
}
console.log(
  restored.length
    ? '\nRestored after prebuild: ' + restored.join(', ')
    : '\nAll settings already present.'
);

if (process.argv.includes('--build')) {
  run(
    // `.\` is load-bearing on Windows, and the comment on run() above already
    // explains why: cmd.exe will not resolve a .bat from the current directory
    // without it. Setting cwd fixed the "cd android &&" half of that problem
    // and left the bare filename, so this still died with "gradlew.bat is not
    // recognized" after a successful prebuild -- the exact failure the comment
    // was written about.
    process.platform === 'win32' ? '.\\gradlew.bat assembleRelease' : './gradlew assembleRelease',
    'android'
  );
  console.log('\nAPK: android/app/build/outputs/apk/release/app-release.apk');
}
